const letters=['A','B','C','D'];
function q(topic, stem, correct, distractors, explanation, tag){
  const opts=[correct,...distractors];
  const seed=stem.length%4;
  const shuffled=opts.map((x,i)=>({x,i})).sort((a,b)=>((a.i+seed*3)%7)-((b.i+seed*3)%7));
  return {topic,q:stem,o:shuffled.map(x=>x.x),a:shuffled.findIndex(x=>x.i===0),e:explanation,tag};
}
function buildBank(topic,cases){
  const bank=[];
  cases.forEach((c,i)=>{
    bank.push(q(topic,`In the ${c.name} scenario, which explanation is the most correct?`,c.m,[c.d1,c.d2,c.d3],c.e,'Mechanism'));
    bank.push(q(topic,`Which assessment finding would be the most important priority in ${c.name}?`,c.p,[c.pd1,c.pd2,c.pd3],c.pe,'Priority'));
    bank.push(q(topic,`Which monitoring plan is most appropriate for ${c.name}?`,c.mo,[c.mod1,c.mod2,c.mod3],c.moe,'Monitoring'));
    bank.push(q(topic,`Which patient-education statement is most accurate for ${c.name}?`,c.te,[c.td1,c.td2,c.td3],c.tee,'Education'));
    bank.push(q(topic,`A student makes four statements about ${c.name}. Which is the most correct?`,c.x,[c.xd1,c.xd2,c.xd3],c.xe,'Clinical reasoning'));
  });
  return bank;
}

